**After** (All steps implemented):
```rust
// Build descriptor arrays as AST nodes directly
fn build_member_descriptor_array<'a>(
    &self,
    metadata: &[MemberMetadata],
    ctx: &TraverseCtx<'a>,
) -> Expression<'a> {
    let descriptors: Vec<ArrayExpressionElement> = metadata.iter()
        .flat_map(|meta| {
            meta.decorator_names.iter().map(|decorator_name| {
                let elements = ctx.ast.vec_from_iter([
                    // Build [decorator, flags, "key", isPrivate] as AST nodes
                    ArrayExpressionElement::from(ctx.ast.expression_identifier_reference(...)),
                    ArrayExpressionElement::from(ctx.ast.expression_numeric_literal(...)),
                    ArrayExpressionElement::from(ctx.ast.expression_string_literal(...)),
                    ArrayExpressionElement::from(ctx.ast.expression_boolean_literal(...)),
                ]);
                ctx.ast.array_expression_element_expression(ctx.ast.expression_array(...))
            })
        })
        .collect();
    ctx.ast.expression_array(SPAN, ctx.ast.vec_from_iter(descriptors), None)
}

// Insert static blocks during traversal
let static_block = self.create_decorator_static_block(class_decorators, member_descriptors, ctx);
class.body.body.push(static_block);

// Modify or create constructor during traversal
if let Some(index) = constructor_index {
    let insert_pos = self.find_super_call_insert_position(&body.statements);
    let init_stmt = self.build_init_proto_if_statement(ctx);
    body.statements.insert(insert_pos, init_stmt);
} else {
    let constructor = self.create_constructor_with_init(class, ctx);
    class.body.body.insert(0, constructor);
}

// Inject variable declarations after traversal
fn inject_variable_declarations_ast<'a>(program: &mut Program<'a>, allocator: &'a Allocator) {
    let ast = AstBuilder::new(allocator);
    if has_static_block {
        let var_decl = create_init_variables_declaration(&ast);
        program.body.insert(index, var_decl);
    }
}
```

